 * @var array    $attributes Block attributes.
 * @var string   $content    Inner block HTML (unused — this block has none).
 * @var WP_Block $block      Block instance (unused).
 *
 * @package AssetPandaGutenberg
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

$props = array(
	'anchor'       => $attributes['anchor'] ?? '',
	'tone'         => $attributes['tone'] ?? 'white',
	'eyebrow'      => $attributes['eyebrow'] ?? '',
	'title'        => $attributes['title'] ?? '',
	'lede'         => $attributes['lede'] ?? '',
	'filter'       => $attributes['filter'] ?? false,
	'all_label'    => $attributes['all_label'] ?? 'All',
	'filter_label' => $attributes['filter_label'] ?? 'Filter by category',
	'search'       => $attributes['search'] ?? false,
	'search_label' => $attributes['search_label'] ?? 'Search',
	'count_label'  => $attributes['count_label'] ?? '',
	'empty_text'   => $attributes['empty_text'] ?? 'Nothing matches that search.',
